-- Forward upgrade for Supabase projects that already applied the initial 001 migration:
-- 1. Widens millisecond epoch columns from 32-bit INTEGER to 64-bit BIGINT.
-- 2. Switches identity columns on platform_settings and audit_logs to GENERATED BY DEFAULT.
-- 3. Adds the platform_store table (with default-deny RLS) for Render free-tier persistence.

ALTER TABLE accounts
  ALTER COLUMN created_at TYPE BIGINT,
  ALTER COLUMN decided_at TYPE BIGINT,
  ALTER COLUMN invite_expires_at TYPE BIGINT,
  ALTER COLUMN last_login_at TYPE BIGINT,
  ALTER COLUMN activated_at TYPE BIGINT;

ALTER TABLE sessions
  ALTER COLUMN created_at TYPE BIGINT,
  ALTER COLUMN last_seen_at TYPE BIGINT;

ALTER TABLE devices
  ALTER COLUMN created_at TYPE BIGINT,
  ALTER COLUMN last_seen_at TYPE BIGINT,
  ALTER COLUMN revoked_at TYPE BIGINT;

ALTER TABLE grants
  ALTER COLUMN created_at TYPE BIGINT,
  ALTER COLUMN expires_at TYPE BIGINT,
  ALTER COLUMN claimed_at TYPE BIGINT;

ALTER TABLE events
  ALTER COLUMN at TYPE BIGINT;

ALTER TABLE audit_logs
  ALTER COLUMN id TYPE BIGINT,
  ALTER COLUMN id SET GENERATED BY DEFAULT,
  ALTER COLUMN occurred_at TYPE BIGINT;

ALTER TABLE platform_settings
  ALTER COLUMN id SET GENERATED BY DEFAULT;

ALTER TABLE account_roles
  ALTER COLUMN granted_at TYPE BIGINT;

ALTER TABLE password_recovery_tokens
  ALTER COLUMN created_at TYPE BIGINT,
  ALTER COLUMN expires_at TYPE BIGINT,
  ALTER COLUMN used_at TYPE BIGINT;

ALTER TABLE email_outbox
  ALTER COLUMN created_at TYPE BIGINT,
  ALTER COLUMN next_attempt_at TYPE BIGINT,
  ALTER COLUMN sent_at TYPE BIGINT;

CREATE TABLE IF NOT EXISTS platform_store (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  data JSONB NOT NULL DEFAULT '{}',
  updated_at BIGINT NOT NULL DEFAULT 0
);

ALTER TABLE platform_store ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'platform_store'
      AND policyname = 'Deny all anon access to platform_store'
  ) THEN
    CREATE POLICY "Deny all anon access to platform_store"
      ON platform_store FOR ALL TO anon USING (false) WITH CHECK (false);
  END IF;
END
$$;
